 using Contoso.Text;

 namespace Contoso.Text.Tests;

 [TestClass]
 public sealed class StringFormatterTests
 {
     private readonly StringFormatter _formatter = new();

     // ─── FormatPhoneNumber ───────────────────────────────────────────

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.AreEqual("(555) 123-4567", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCode()
     {
         var result = _formatter.FormatPhoneNumber("2125551234");

         Assert.StartsWith("(212)", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_EndsWithLastFour()
     {
         var result = _formatter.FormatPhoneNumber("2125551234");

         Assert.EndsWith("1234", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ContainsDash()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.Contains("-", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_Null_ThrowsArgumentNullException()
     {
         var ex = Assert.ThrowsExactly<ArgumentNullException>(
             () => _formatter.FormatPhoneNumber(null!));

         Assert.AreEqual("digits", ex.ParamName);
     }

     [TestMethod]
     [DataRow("123", DisplayName = "Too short")]
     [DataRow("12345678901", DisplayName = "Too long")]
     [DataRow("", DisplayName = "Empty")]
     public void FormatPhoneNumber_InvalidLength_ThrowsArgumentException(string digits)
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.FormatPhoneNumber(digits));
     }

     // ─── BuildGreeting ───────────────────────────────────────────────

     [TestMethod]
     public void BuildGreeting_WithDefaultTitle_StartsWithDearMr()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.StartsWith("Dear Mr.", result);
     }

     [TestMethod]
     public void BuildGreeting_WithDefaultTitle_EndsWithComma()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.EndsWith(",", result);
     }

     [TestMethod]
     public void BuildGreeting_WithCustomTitle_ContainsTitle()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.Contains("Dr.", result);
         Assert.StartsWith("Dear Dr.", result);
     }

     [TestMethod]
     public void BuildGreeting_WithCustomTitle_ContainsName()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.Contains("Johnson", result);
     }

     [TestMethod]
     public void BuildGreeting_FullFormat_ReturnsExpected()
     {
         var result = _formatter.BuildGreeting("Doe", "Ms.");

         Assert.AreEqual("Dear Ms. Doe,", result);
     }

     [TestMethod]
     [DataRow(null)]
     [DataRow("")]
     [DataRow("   ")]
     public void BuildGreeting_InvalidName_ThrowsArgumentException(string? name)
     {
         Assert.Throws<ArgumentException>(
             () => _formatter.BuildGreeting(name!));
     }

     // ─── GenerateSlug ────────────────────────────────────────────────

     [TestMethod]
     [DataRow("Hello World", "hello-world")]
     [DataRow("  Leading Spaces  ", "leading-spaces")]
     [DataRow("UPPER CASE", "upper-case")]
     [DataRow("Special!@#Characters", "special-characters")]
     [DataRow("multiple   spaces", "multiple-spaces")]
     public void GenerateSlug_VariousInputs_ReturnsExpectedSlug(string title, string expected)
     {
         var result = _formatter.GenerateSlug(title);

         Assert.AreEqual(expected, result);
     }

     [TestMethod]
     public void GenerateSlug_ValidTitle_MatchesSlugPattern()
     {
         var result = _formatter.GenerateSlug("My Blog Post!");

         Assert.MatchesRegex(@"^[a-z0-9]+(-[a-z0-9]+)*$", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleWithPrefix_StartsWithLowercase()
     {
         var result = _formatter.GenerateSlug("API Reference Guide");

         Assert.StartsWith("api", result);
     }

     [TestMethod]
     [DataRow(null)]
     [DataRow("")]
     [DataRow("   ")]
     public void GenerateSlug_InvalidTitle_ThrowsArgumentException(string? title)
     {
         Assert.Throws<ArgumentException>(
             () => _formatter.GenerateSlug(title!));
     }

     // ─── FormatCurrency ──────────────────────────────────────────────

     [TestMethod]
     public void FormatCurrency_DefaultSymbol_StartsWithDollar()
     {
         var result = _formatter.FormatCurrency(9.99m);

         Assert.StartsWith("$", result);
     }

     [TestMethod]
     public void FormatCurrency_CustomSymbol_StartsWithSymbol()
     {
         var result = _formatter.FormatCurrency(19.99m, "€");

         Assert.StartsWith("€", result);
     }

     [TestMethod]
     public void FormatCurrency_WholeNumber_EndsWithTwoDecimals()
     {
         var result = _formatter.FormatCurrency(42m);

         Assert.EndsWith(".00", result);
     }

     [TestMethod]
     public void FormatCurrency_WithCents_ReturnsFormattedValue()
     {
         var result = _formatter.FormatCurrency(19.99m, "€");

         Assert.AreEqual("€19.99", result);
     }

     [TestMethod]
     [DataRow(0, "$0.00")]
     [DataRow(1000.5, "$1000.50")]
     [DataRow(-5.25, "$-5.25")]
     public void FormatCurrency_VariousAmounts_ReturnsExpected(double amount, string expected)
     {
         var result = _formatter.FormatCurrency((decimal)amount);

         Assert.AreEqual(expected, result);
     }
 }

